  "items": [
    {
      "id": "R1",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "연합형 게임을 설명하는 데 쓰인 ‘연합’의 뜻을 풀이하므로 정의 관계이다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "협력 결과의 분배 기준이라는 일반적 설명에 섀플리 값이라는 대표 사례를 제시한다."
    },
    {
      "id": "R3",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞서 소개한 섀플리 값이 무엇인지 기여 정도에 따른 총비용 분배 기준으로 뜻을 풀이한다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "모든 연합 형성 경우를 고려한다는 사실이 기회 균등성을 가진다는 판단의 근거이다."
    },
    {
      "id": "R5",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "참여에 따른 비용 증가분에 비례하여 분담한다는 사실이 기여 공정성을 가진다는 판단을 뒷받침한다."
    },
    {
      "id": "R6",
      "type": "PROCESS",
      "otherName": "",
      "reason": "한계기여도를 먼저 계산하고 그 결과에 가중치를 곱해 합산하는 다음 단계로 진행한다."
    },
    {
      "id": "R7",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "총비용의 증가분이라는 한계기여도의 뜻을 참여 후 비용에서 참여 전 비용을 빼는 식으로 나타낸다."
    },
    {
      "id": "R8",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "섀플리 값 계산에 사용되는 ‘가중치’의 뜻을 특정 순서의 연합이 나타날 확률로 풀이한다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "참여 순서에 따라 한계기여도가 달라진다는 사실을 가중치를 곱하는 계산 방식의 이유로 제시한다."
    },
    {
      "id": "R10",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "가중치를 곱하는 것은 모든 참여 순서에 동일한 중요성을 부여하려는 목적을 위한 수단이다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "비용 증가분에 비례하여 분담한다는 설명을 한계기여도의 계산 절차로 자세히 풀어 준다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모든 연합 형성 경우를 고려한다는 기회 균등성을 각 참여 순서에 가중치를 부여하는 방식으로 구체화한다."
    },
    {
      "id": "R13",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 제시한 한계기여도 계산 원리를 갑과 을의 여행 비용 분담 사례에 적용한다."
    },
    {
      "id": "R14",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "단독 비용과 동승 총비용이라는 수치 자료로부터 갑 다음 을의 순서에서 한계기여도를 계산한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "단독 비용과 동승 총비용이라는 수치 자료로부터 을 다음 갑의 순서에서 한계기여도를 계산한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "탑승 전 비용이 없다는 사실을 계산 근거로 삼아 갑의 한계기여도가 2,000원임을 도출한다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 동승 순서를 한계기여도라는 동일한 기준으로 비교하여 갑과 을의 값이 달라짐을 보여 준다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "갑 다음 을의 순서에서 계산한 구체적 사례를 순서에 따라 한계기여도가 달라진다는 일반적 성질로 연결한다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "을 다음 갑의 순서에서 계산한 구체적 사례를 순서에 따라 한계기여도가 달라진다는 일반적 성질로 연결한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "동승 순서에 따라 한계기여도가 달라진다는 사실을 모든 경우의 값에 가중치를 곱하는 이유로 제시한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "가능한 동승 순서가 두 가지라는 자료를 바탕으로 각 순서의 발생 확률을 계산한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "각 순서의 발생 확률과 가중치의 정의를 근거로 가중치가 1/2이라는 값을 도출한다."
    },
    {
      "id": "R23",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "특정 순서의 발생 확률을 가중치로 삼는 원리를 두 사람의 동승 사례에 적용한다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "가중 한계기여도를 개인별로 합산하는 일반 계산법을 갑과 을의 섀플리 값 산출에 적용한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "갑 다음 을의 순서에서 얻은 한계기여도 수치가 개인별 섀플리 값을 계산하는 자료로 쓰인다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "을 다음 갑의 순서에서 얻은 한계기여도 수치가 개인별 섀플리 값을 계산하는 자료로 쓰인다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "각 순서의 가중치가 1/2이라는 계산 자료를 이용하여 갑과 을의 섀플리 값을 도출한다."
    },
    {
      "id": "R28",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "갑과 을의 사례에서 확인한 합계의 성질을 모든 경제주체의 섀플리 값에 관한 일반적 성질로 확장한다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "섀플리 값의 합이 총비용과 같다는 성질을 공정한 총비용 분배 기준이라는 결론의 근거로 제시한다."
    },
    {
      "id": "R30",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "기회 균등성과 기여 공정성을 갖춘 분배 기준이라는 앞의 설명을 결론에서 같은 뜻으로 다시 말한다."
    },
    {
      "id": "R31",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "공정한 비용 분배 기준인 섀플리 값을 사회 기반 시설 설치 비용이라는 새로운 현실 영역에 가져다 쓴다."
    }
  ]
}

